// New dev consumer only. Prior v0 consumer/source/selected art remain immutable.
const freeze=v=>{if(v&&typeof v==='object'){Object.freeze(v);for(const q of Object.values(v))freeze(q);}return v;};
export const point2=v=>Array.isArray(v)&&Object.getPrototypeOf(v)===Array.prototype&&v.length===2&&Reflect.ownKeys(v).length===3&&['0','1','length'].every(k=>Object.hasOwn(v,k)&&Object.hasOwn(Object.getOwnPropertyDescriptor(v,k),'value'))&&Number.isInteger(v[0])&&Number.isInteger(v[1])&&v[0]>=0&&v[0]<4294&&v[1]>=0&&v[1]<2400;
const required=['pointId','mapId','revision','state','artSHA','foot','facing'],allowed=new Set([...required,'inputKind','label','signSHA']);
const record=r=>!!r&&Object.getPrototypeOf(r)===Object.prototype&&Reflect.ownKeys(r).every(k=>typeof k==='string'&&allowed.has(k)&&Object.hasOwn(Object.getOwnPropertyDescriptor(r,k),'value'))&&required.every(k=>Object.hasOwn(r,k));
export class GohyeonV3Host{
 constructor(contract){Object.defineProperty(this,'input',{value:freeze(structuredClone(contract)),writable:false});Object.defineProperty(this,'c',{value:this.input.hub,writable:false});this.epoch=0;this.active=true;this.native=null;this.pending=false;}
 safe(foot,state){if(!point2(foot)||!['OPEN','CLOSED'].includes(state))return false;const[x,y]=foot;for(let yy=y-18;yy<=y+18;yy++)for(let xx=x-24;xx<=x+24;xx++){if(xx<0||yy<0||xx>=4294||yy>=2400)return false;if(xx>=3964&&xx<4134&&yy>=2265)return false;const e=this.c.eventBody;if(xx>=e[0]&&xx<e[2]&&yy>=e[1]&&yy<e[3])return false;if(state==='CLOSED'&&xx>=4214&&yy>=1040&&yy<1350)return false;if(!this.c.manualSafeCorridors.some(({rectLTRB:[a,b,c,d]})=>xx>=a&&xx<c&&yy>=b&&yy<d))return false;}
 return this.input.signs.every(({contract:s})=>{const[a,b,c,d]=s.solidCandidate;return !(x+24>=a&&x-24<c&&y+18>=b&&y-18<d)});}
 inspect(req){if(!record(req)||!point2(req.foot))return{ok:false,reason:'STRICT_INPUT_SHAPE'};const a=this.c.anchors.find(x=>x.sourcePoint.id===req.pointId);if(!this.active||!a||req.revision!==this.c.revision||req.mapId!==this.c.mapId)return{ok:false,reason:'IDENTITY_REVISION'};if(!['OPEN','CLOSED'].includes(req.state)||req.artSHA!==this.c.art[req.state==='OPEN'?0:1].sha256)return{ok:false,reason:'STATE_ART'};if(!this.safe(req.foot,req.state)||req.foot[0]!==a.interactionFoot[0]||req.foot[1]!==a.interactionFoot[1]||req.facing!==a.facing)return{ok:false,reason:'FOOT_FACING'};if(Math.abs(a.objectAnchor[0]-req.foot[0])+Math.abs(a.objectAnchor[1]-req.foot[1])>48)return{ok:false,reason:'RANGE48'};return{ok:true,pointId:a.sourcePoint.id,kind:a.sourcePoint.kind,presentation:a.presentationStatus,sourceHostRequired:true};}
 async request(req,source){const q=this.inspect(req);if(!q.ok)return q;const sign=this.input.signs.find(x=>x.contract.pointId===q.pointId)?.contract;if(sign&&(req.inputKind!=='explicit-interact'||req.label!==sign.interactionLabel||req.signSHA!==sign.art.sha256))return{ok:false,reason:'EXPLICIT_EXACT_VISIBLE_DESTINATION_REQUIRED'};if(['PRESENTATION_NOT_AUTHORED','SOURCE_MESSAGE_MISSING'].includes(q.presentation))return{ok:false,reason:q.presentation,geometry:q};if(this.pending)return{ok:false,reason:'SOURCE_BUSY'};const e=this.epoch;this.pending=true;try{const r=await source.interact(q.pointId);if(e!==this.epoch||!this.active)return{ok:false,reason:'STALE_SOURCE_COMPLETION_RECONCILE_REQUIRED'};return{ok:true,sourceResult:r,nativeWarpApplied:false};}finally{this.pending=false;}}
 view(pointId){const q=this.input.signs.find(x=>x.contract.pointId===pointId);if(!q)return null;const s=q.contract;return{pointId,revision:this.c.revision,exactLabel:s.interactionLabel,layer:{src:q.file,sha256:s.art.sha256,origin:s.art.worldOrigin,pivot:s.art.worldPivot},sorting:'footY; static sign before actor on equal pivotY',inputKind:'explicit-interact',autoTouch:false,browser:'NOT_RUN'};}
 async interact(req,source){const valid=this.inspect(req);if(!valid.ok)return valid;const q=this.input.signs.find(x=>x.contract.pointId===req.pointId),s=q?.contract;if(!s||req.inputKind!=='explicit-interact'||req.label!==s.interactionLabel||req.signSHA!==s.art.sha256)return{ok:false,reason:'EXPLICIT_EXACT_VISIBLE_DESTINATION_REQUIRED'};const r=await this.request(req,source);if(!r.ok)return r;if(source.snapshot().position.scene!==s.targetMapId)return{ok:false,reason:'SOURCE_TARGET_MISMATCH_RECONCILE'};this.native={mapId:s.targetMapId,foot:[...q.pair.arrivalLanding]};return{ok:true,devNativeMemoryOnly:true,native:this.native,productionInstalled:false};}
 leave(){this.active=false;this.epoch++;}
}
